const orderByPoints = (nums) => {
  const digitSum = (num) =>
    Math.abs(num)
      .toString()
      .split("")
      .reduce((sum, digit) => sum + Number(digit), 0);

  return nums
    .map((num, index) => ({ num, index }))
    .sort((a, b) => digitSum(a.num) - digitSum(b.num) || a.index - b.index)
    .map(({ num }) => num);
};

